const KEY='kontur-audio-v1';
let settings={enabled:true,volume:.28};try{Object.assign(settings,JSON.parse(localStorage.getItem(KEY)||'{}'));}catch{}
let context,master,timer,step=0,theme='menu',alarm=false;
function note(freq,when,length,gain=.1,type='sine'){if(!context||!settings.enabled)return;const o=context.createOscillator(),g=context.createGain();o.type=type;o.frequency.setValueAtTime(freq,when);g.gain.setValueAtTime(0,when);g.gain.linearRampToValueAtTime(gain,when+.015);g.gain.exponentialRampToValueAtTime(.0001,when+length);o.connect(g).connect(master);o.start(when);o.stop(when+length+.02);}
function tick(){if(!context||context.state!=='running'||document.hidden||!settings.enabled)return;if(alarm&&step%12===0){const o=context.createOscillator(),g=context.createGain(),t=context.currentTime;o.type='sine';o.frequency.setValueAtTime(430,t);o.frequency.linearRampToValueAtTime(880,t+.8);o.frequency.linearRampToValueAtTime(430,t+1.6);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.07,t+.1);g.gain.linearRampToValueAtTime(0,t+1.7);o.connect(g).connect(master);o.start(t);o.stop(t+1.8);}const t=context.currentTime+.025,roots=theme==='crisis'?[55,55,65.4,49]:theme==='story'?[55,43.65,49,41.2]:[65.4,55,73.4,49],root=roots[Math.floor(step/16)%roots.length];note(root*(step%4===0?1:2),t,.28,.065,'triangle');if(step%4===0){note(78,t,.12,.16);note(39,t,.23,.12);}if(step%8===4)note(190,t,.06,.035,'sawtooth');if(step%2===0)note(root*[4,6,8,6,4,5,6,3][Math.floor(step/2)%8],t,.18,.025,'triangle');if(step%16===0)for(const n of [2,2.38,3])note(root*n,t,2.1,.023);step++;}
export const audio={alarm(value){alarm=!!value;},get settings(){return {...settings};},async start(mode='menu'){theme=mode;try{if(!context){context=new (window.AudioContext||window.webkitAudioContext)();master=context.createGain();master.connect(context.destination);master.gain.value=settings.enabled?settings.volume:0;timer=setInterval(tick,180);}await context.resume();}catch{}},theme(mode){theme=mode;step=0;},set(enabled,volume=settings.volume){settings={enabled:!!enabled,volume:Math.max(0,Math.min(1,+volume||0))};try{localStorage.setItem(KEY,JSON.stringify(settings));}catch{}if(master)master.gain.setTargetAtTime(settings.enabled?settings.volume:0,context.currentTime,.15);},transition(){if(context){const t=context.currentTime;[130.8,196,261.6,311.1].forEach((f,i)=>note(f,t+i*.09,.65,.06,'triangle'));}},success(){if(context)[261.6,329.6,392,523.2].forEach((f,i)=>note(f,context.currentTime+i*.12,.6,.08,'triangle'));}};
